<?php declare(strict_types=1); namespace App\Modules\Tourism\Controllers; use App\Core\Auth;use App\Core\Authorization;use App\Core\Controller;use RuntimeException;use Throwable;use App\Modules\Tourism\Services\TourismReviewService; final class TourismReviewController extends Controller{private TourismReviewService $s;private Authorization $a;public function __construct(){$this->s=new TourismReviewService();$this->a=new Authorization();}private function allow($p,$r='/tourism'){try{$this->a->authorize($p);return true;}catch(RuntimeException $e){flash('error',$e->getMessage());redirect($r);return false;}}public function index(){if(!$this->allow('tourism.reviews.view'))return;$this->view('Tourism::Reviews.index',['title'=>'Tourism Reviews','reviews'=>$this->s->all((int)Auth::tenantId())]);}public function status($id){if(!$this->allow('tourism.reviews.moderate','/tourism/reviews'))return;try{$this->s->status((int)Auth::tenantId(),$id,(string)($_POST['status']??'Pending'));flash('success','Review status updated.');}catch(Throwable $e){flash('error',$e->getMessage());}redirect('/tourism/reviews');}}